// The application frame: sidebar, header, main. Its `inset` variant gives it a panel to paint, and a
// unit that paints is a Component, not a Layout (ADR-0047). The slots stay
// consumer-owned; every value it reads goes through its own `app-shell` Cmp domain.
import { useEffect, useRef, useState, type CSSProperties, type HTMLAttributes, type ReactNode, type Ref } from "react";
import "./AppShell.css";

export interface AppShellProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * How the sidebar and the page are told apart. `plain` does not separate them; `divided` puts the
   * sidebar on its own backdrop behind a rule; `floating` lifts the sidebar onto a panel; `inset`
   * lifts the header and page content onto one panel beside the sidebar. Each needs a sidebar
   * column to separate, so it takes effect only with a `sidebar` or a `rail` and from the medium
   * step up; anywhere else the shell renders as `plain`. With a rail, `divided` paints the rail and
   * the sidebar as one backdrop with the rule at its end, `floating` lifts the sidebar alone while
   * the rail stays on the canvas, and `inset` leaves both on the canvas beside its panel.
   *
   * @default "plain"
   */
  variant?: "plain" | "divided" | "floating" | "inset";
  /** Desktop sidebar content supplied by the consumer. */
  sidebar?: ReactNode;
  /**
   * A narrow navigation column before the sidebar, such as a `NavigationRail`: its own grid track,
   * sized to its content, shown from the medium step up and hidden below it like the sidebar (there
   * `navTrigger` or `bottomNav` is the route). The rail and the sidebar read as one region, so the
   * sidebar's inset surrounds both and separates them once.
   *
   * It is the trigger that lives outside the sidebar slot, so with a rail `sidebarCollapsed` folds
   * the sidebar to nothing while the rail stays.
   */
  rail?: ReactNode;
  /** Header bar content supplied by the consumer. */
  header?: ReactNode;
  /**
   * The way to the sidebar where there is no sidebar column: below the medium step the column is
   * hidden, so a consumer passes a control here (a Button that opens a Drawer holding the same
   * sidebar content) and the shell shows it on its own line above the header ONLY below that step. The
   * shell renders none of its own, like every other slot: the control and the Drawer are the
   * consumer's, because a Layout owns arrangement and draws no content (tier-convention.md § Tiers).
   */
  navTrigger?: ReactNode;
  /**
   * The navigation as a bar along the bottom where there is no sidebar column: a phone app's tab bar
   * (a `BottomNav`). Shown below the medium step only, like `navTrigger`; from that step the sidebar
   * column is the route. The shell keeps room at the end of the page so the bar never covers the
   * last content (WCAG 2.4.11).
   */
  bottomNav?: ReactNode;
  /**
   * A bar docked ABOVE `bottomNav`, such as a hub's conversion bar (a `DockedBar`): fixed to the
   * window's bottom while there is no tab bar, and stacked on the tab bar's top edge where there is
   * one, so both stay in reach. Shown at every width, unlike `bottomNav`: a `DockedBar
   * width="constrained"` floats centred from the step up instead. The shell keeps room at the end of
   * the page for both bars together (WCAG 2.4.11).
   */
  bottomBar?: ReactNode;
  /**
   * Main page content. The main region already pads by the page's grid margin and caps its reading
   * width, so a `Container` inside it takes `padding="none"` (Feed does): a padded one adds the margin
   * a second time, which on a phone puts content 48px in instead of 24.
   */
  children: ReactNode;
  /**
   * The step from which the wide layout applies: the sidebar column instead of `navTrigger`, and no
   * `bottomNav`. A product whose phone layout runs up to a tablet switches at `large`.
   *
   * @default "medium"
   */
  breakpoint?: "medium" | "large";
  /** Width of the sidebar column from the `breakpoint` step up (default `16rem`). */
  sidebarWidth?: string;
  /**
   * Whether the sidebar column is collapsed to {@link collapsedSidebarWidth}.
   *
   * CONTROLLED, and deliberately so: every Layout in this tier is stateless, and the consumer needs
   * the same boolean anyway to render its own toggle — a Layout owns arrangement and renders no
   * content of its own, so the control that flips this is never this component's to draw
   * (`tier-convention.md` § Tiers). Precedent for the capability living in the layout rather than in
   * each app: Ant Design's `Layout.Sider` (`collapsed` / `onCollapse`) and shadcn's `Sidebar`
   * (`collapsible`), both of which keep the trigger separate too.
   *
   * The sidebar stays MOUNTED when collapsed, which is the point of the prop: dropping the `sidebar`
   * slot instead also collapses the column, and takes the panel's scroll position, focus and any
   * transient state with it.
   *
   * With a `rail` the sidebar folds to zero: its content keeps the open width and is clipped as the
   * column closes, so it slides shut rather than reflowing, and the folded sidebar is `inert`, so
   * focus cannot reach what is not shown. A control inside the sidebar that folds it (a panel's own
   * close) moves focus out first, to the rail item that reopens it: focus left inside an inert
   * column falls to the page (WCAG 2.4.3).
   */
  sidebarCollapsed?: boolean;
  /**
   * Width the sidebar column takes while collapsed (default `5.5rem`).
   *
   * Not zero, and that is a functional default rather than a taste one: a toggle rendered inside the
   * sidebar disappears with the column at zero, leaving no way back. Ant Design ships `collapsedWidth`
   * at 80 for the same reason and documents that zero needs "a special trigger"; shadcn's equivalent
   * mode is named `icon`. Pass `0` only when the consumer's trigger lives outside this slot.
   *
   * Ignored with a `rail`, which is that trigger: the sidebar then folds to zero.
   */
  collapsedSidebarWidth?: string;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

/**
 * One CSS knob is public: `--sd-app-shell-sidebar-gutter`, the sidebar's trailing inset, the same rung
 * as its padding by default. Set it on the shell to narrow the gap to a page beside it that keeps its own
 * margin (the `inset` variant's panel), so the two do not sum. The open column's content width
 * subtracts it, so a rail's sliding sidebar keeps its content on the column it has.
 */
export function AppShell({
  variant = "plain",
  sidebar,
  rail,
  header,
  navTrigger,
  bottomNav,
  bottomBar,
  children,
  breakpoint = "medium",
  sidebarWidth = "16rem",
  sidebarCollapsed,
  collapsedSidebarWidth = "5.5rem",
  className,
  style,
  ref,
  ...rest
}: AppShellProps) {
  /* How far the bottom bars reach up from the window's bottom edge, measured: a bar sizes to its
     content and floats at a margin it owns, so no token can say it, and an estimate either wastes
     room or lets a bar cover the last row. `navReach` is the tab bar's, which lifts `bottomBar` onto
     its top edge; `clearance` is the higher of the two, the room the page keeps. Zero where hidden. */
  const navRef = useRef<HTMLDivElement>(null);
  const barRef = useRef<HTMLDivElement>(null);
  const [navReach, setNavReach] = useState(0);
  const [clearance, setClearance] = useState(0);
  useEffect(() => {
    // The fixed element itself, wherever it sits in the slot: a wrapper around it is in flow and
    // zero tall, so measuring the slot's first child would read no bar at all.
    const fixedIn = (slot: HTMLElement | null) =>
      slot
        ? ([...slot.querySelectorAll("*")].find((el) => getComputedStyle(el).position === "fixed") ?? slot.firstElementChild)
        : null;
    const bars = [fixedIn(navRef.current), fixedIn(barRef.current)];
    const reach = (el: Element | null) => {
      const r = el?.getBoundingClientRect();
      return r?.height ? Math.ceil(window.innerHeight - r.top) : 0;
    };
    const measure = () => {
      setNavReach(reach(bars[0]));
      setClearance(Math.max(reach(bars[0]), reach(bars[1])));
    };
    measure();
    const observer = new ResizeObserver(measure);
    for (const bar of bars) if (bar) observer.observe(bar);
    window.addEventListener("resize", measure);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", measure);
    };
    // `navReach` too: the bar moves when its offset lands without changing size, so nothing observed
    // fires, and its reach is read again once it sits on the tab bar.
  }, [bottomNav, bottomBar, navReach]);
  return (
    <div
      {...rest}
      ref={ref}
      data-variant={variant}
      data-has-sidebar={sidebar ? "true" : undefined}
      data-sidebar-collapsed={sidebar && sidebarCollapsed ? "true" : undefined}
      data-has-rail={rail ? "true" : undefined}
      className={className ? `sd-app-shell ${className}` : "sd-app-shell"}
      data-breakpoint={breakpoint}
      style={
        {
          "--sd-app-shell-sidebar-width": sidebarWidth,
          // A bare "0" is a number, not a length, and `min(<length>, 0)` is invalid CSS, so every
          // rule that budgets against this width would drop and paint at full size.
          "--sd-app-shell-bottom-nav-clearance": `${clearance}px`,
          // A rail is the trigger outside the slot, so the sidebar beside it folds to nothing.
          "--sd-app-shell-sidebar-collapsed-width":
            rail || collapsedSidebarWidth.trim() === "0" ? "0px" : collapsedSidebarWidth,
          ...style,
        } as CSSProperties
      }
    >
      {rail && (
        <div
          className="sd-app-shell__rail"
          data-breakpoint={breakpoint}
          data-variant={variant}
          // Whether the rail ends the region, which decides where `divided` draws its rule.
          data-sidebar-open={sidebar && !sidebarCollapsed ? "true" : undefined}
        >
          {rail}
        </div>
      )}
      {sidebar && (
        <aside
          className="sd-app-shell__sidebar"
          data-breakpoint={breakpoint}
          // The state is carried on the element that reacts to it, so the CSS needs no descendant
          // combinator (component-contract.md §6 rule 2).
          data-collapsed={sidebarCollapsed ? "true" : undefined}
          data-variant={variant}
          data-has-rail={rail ? "true" : undefined}
          // Folded beside a rail it is zero wide, so nothing in it may take focus.
          inert={Boolean(rail && sidebarCollapsed)}
        >
          {sidebar}
        </aside>
      )}
      {/* Header and main share one panel in both variants, so the DOM has one shape; only `inset`
          paints it. The variant is mirrored here because the panel is the element that reacts. */}
      <div
        className="sd-app-shell__panel"
        data-breakpoint={breakpoint}
        data-variant={variant}
        // A rail is a column to separate from as much as a sidebar is.
        data-has-sidebar={sidebar || rail ? "true" : undefined}
      >
        {header ? (
          <header className="sd-app-shell__header" data-breakpoint={breakpoint} data-has-nav-trigger={navTrigger ? "true" : undefined}>
            {navTrigger ? (
              <>
                <div className="sd-app-shell__nav-trigger" data-breakpoint={breakpoint}>{navTrigger}</div>
                <div className="sd-app-shell__header-content" data-breakpoint={breakpoint}>{header}</div>
              </>
            ) : (
              header
            )}
          </header>
        ) : (
          // A trigger and no header: a bar of its own, hidden by CSS wherever the sidebar column
          // shows, so it draws no empty band there and a stateful trigger stays mounted.
          navTrigger && <header className="sd-app-shell__nav-bar" data-breakpoint={breakpoint}>{navTrigger}</header>
        )}
        <main
          className="sd-app-shell__main"
          data-breakpoint={breakpoint}
          data-has-bottom-nav={bottomNav ? "true" : undefined}
          data-has-bottom-bar={bottomBar ? "true" : undefined}
        >
          {children}
        </main>
      </div>
      {/* Before the tab bar in the DOM, so at the same layer it reads first and paints under nothing.
          The tab bar's measured reach is handed to the bar as DockedBar's public offset knob. */}
      {bottomBar && (
        <div
          ref={barRef}
          className="sd-app-shell__bottom-bar"
          style={{ "--sd-docked-bar-offset": `${navReach}px` } as CSSProperties}
        >
          {bottomBar}
        </div>
      )}
      {bottomNav && (
        <div ref={navRef} className="sd-app-shell__bottom-nav" data-breakpoint={breakpoint}>
          {bottomNav}
        </div>
      )}
    </div>
  );
}

/* AppShell.css — .sd-app-shell (Component: the application frame, ADR-0047)
   Mobile-first: a single fluid column by default (sidebar hidden); at the shared md
   breakpoint (min-width, per the DS ladder) the consumer-provided sidebar column appears.
   The panel holding header and main uses `grid-column: -2 / -1` (the LAST column) so it lands in
   col 1 when single-column and last beside the sidebar and rail columns — breakpoint-independent.
   The sidebar counts from the end the same way (`-3 / -2`), so it is column 1 alone and column 2
   after a rail.
   --sd-app-shell-sidebar-width is a local intermediate (set inline from the `sidebarWidth`
   prop), not a token. */
.sd-app-shell {
  /* Block inheritance of the inline per-instance --sd-app-shell-sidebar-* vars (see Container.css): custom
     properties inherit, so a nested shell would otherwise read its ancestor's width. */
  --sd-app-shell-sidebar-width: initial;
  --sd-app-shell-sidebar-collapsed-width: initial;
  --sd-app-shell-bottom-nav-clearance: initial;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-height: 100vh;
}

/* The sidebar column owns its content's inset, as header and main own theirs, so whatever sits in
   the slot (a Sidebar, a SidePanel) draws flush and the same content reused in a Drawer does not
   carry a second inset inside the Drawer's own. Its trailing inset is its own token,
   `--sd-app-shell-sidebar-gutter` (AppShell.tsx says when a consumer sets it). */
.sd-app-shell__sidebar {
  grid-column: -3 / -2;
  grid-row: 1;
  min-width: 0;
  display: none;
  padding: var(--sd-app-shell-sidebar-padding);
  padding-inline-end: var(--sd-app-shell-sidebar-gutter);
}

/* A narrowed column must also CLIP, or the prop is a lie: the track went to zero and the slot's
   content — which does not shrink below its own min-content — kept painting over the page, measured
   on the `collapsedSidebarWidth="0"` story. Clipping is what the collapsed state means everywhere
   this pattern exists (antd and shadcn both hide the labels rather than let them spill). Not a
   scrollport: `overflow: hidden` clips, it does not take a tab stop, so the rule
   "Layout slot wrappers do not become scrollports" is untouched. */
.sd-app-shell__sidebar[data-collapsed] {
  overflow: hidden;
}

/* The rail: a column of its own before the sidebar, sized to its content. It takes the sidebar's
   inset, so the two read as one region: the same inset around both, and once between them. */
.sd-app-shell__rail {
  grid-column: 1;
  grid-row: 1;
  display: none;
  padding: var(--sd-app-shell-sidebar-padding);
}

/* Header and main, stacked. Unpainted in `plain`; the `inset` rule below paints it. */
.sd-app-shell__panel {
  /* The inline inset header and main share: the page frame's margin, plus half of whatever the panel
     is wider than the frame's cap, so the content stops where a LayoutGrid page's does and centres
     past it. A percentage padding resolves against this panel, which is the parts' containing block.
     Set here, read by the parts (contract §6.5): one relay per part, each from its own inset token. */
  --sd-app-shell-header-inline-current: calc(
    max(0px, (100% - var(--sd-app-shell-main-max-width)) / 2) + var(--sd-app-shell-header-padding-inline)
  );
  --sd-app-shell-main-inline-current: calc(
    max(0px, (100% - var(--sd-app-shell-main-max-width)) / 2) + var(--sd-app-shell-main-padding-inline)
  );
  grid-column: -2 / -1;
  grid-row: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  /* The frame a page band runs edge to edge of (Separator `band`), never past the sidebar. */
  container-type: inline-size;
}

/* header and main share an INLINE inset or their contents never line up: `space.medium` is flat
   at 16 across every breakpoint while `space.large` steps 20 -> 24, so two different insets would
   sit 4px apart on a phone and 8px from 768 up. The block padding stays tighter, because a header is deliberately
   tighter vertically; only the inline half is shared, and it is the page frame's own margin. */
.sd-app-shell__header {
  min-width: 0;
  padding-block: var(--sd-app-shell-header-padding-block);
  padding-inline: var(--sd-app-shell-header-inline-current);
}

/* The nav trigger takes its own line ABOVE the header content, the shape of a phone's large-title
   screen. Shown by default and hidden from the step at which the sidebar column appears (below), so
   exactly one of the two routes to the navigation is ever reachable. Beside the header it would start
   the title, its description and its actions a trigger's width in from the page content below, so
   every left edge under the header would step back out. */
.sd-app-shell__header[data-has-nav-trigger] {
  display: flex;
  flex-direction: column;
  gap: var(--sd-app-shell-header-gap);
}
.sd-app-shell__nav-trigger {
  align-self: flex-start;
}
/* A trigger with no header to sit above: the header's padding, so it starts where a header would. */
.sd-app-shell__nav-bar {
  display: flex;
  padding-block: var(--sd-app-shell-header-padding-block);
  padding-inline: var(--sd-app-shell-header-inline-current);
}
.sd-app-shell__header-content {
  flex: 1;
  min-width: 0;
}

.sd-app-shell__main {
  flex: 1;
  min-width: 0;
  padding-block: var(--sd-app-shell-main-padding-block);
  padding-inline: var(--sd-app-shell-main-inline-current);
}

/* A fixed bottom bar floats over the page's end, so the page keeps that much room after its last
   content: the tab bar's, or the bar stacked on it, whichever reaches higher.
   `--sd-app-shell-bottom-nav-clearance` is a local intermediate the tsx measures, not a token. */
.sd-app-shell__main[data-has-bottom-nav],
.sd-app-shell__main[data-has-bottom-bar] {
  padding-block-end: calc(
    var(--sd-app-shell-main-padding-block) + var(--sd-app-shell-bottom-nav-clearance)
  );
}

@media (min-width: 768px) {
  /* BOTH tracks are `minmax(0, …)`, and the expanded one needs it for a reason that is not its own:
     a track only interpolates into a track of the SAME shape, so a bare length here against a
     `minmax()` when collapsed made the transition below inert — measured, the column jumped
     256 -> 56 in one frame with the transition property correctly applied. */
  .sd-app-shell[data-has-sidebar]:not([data-breakpoint="large"]) {
    grid-template-columns: minmax(0, var(--sd-app-shell-sidebar-width, 16rem)) minmax(0, 1fr);
  }
  /* the sidebar element only exists when a sidebar is provided (data-has-sidebar), so
     revealing it here needs no extra qualifier — no descendant combinator. */
  .sd-app-shell__sidebar:not([data-breakpoint="large"]) {
    display: block;
  }
  /* Both routes to the navigation that only exist without the column. Hidden, not unmounted, so a
     stateful trigger survives the step, and a trigger-only bar leaves no empty band above the page. */
  .sd-app-shell__nav-trigger:not([data-breakpoint="large"]),
  .sd-app-shell__nav-bar:not([data-breakpoint="large"]),
  .sd-app-shell__bottom-nav:not([data-breakpoint="large"]) {
    display: none;
  }
  .sd-app-shell__main[data-has-bottom-nav]:not([data-has-bottom-bar]):not([data-breakpoint="large"]) {
    padding-block-end: var(--sd-app-shell-main-padding-block);
  }

  /* Divided: the sidebar is a section of the page plane, one backdrop step off it, behind a rule. */
  .sd-app-shell__sidebar[data-variant="divided"]:not([data-breakpoint="large"]) {
    background: var(--sd-app-shell-sidebar-background);
    border-inline-end: var(--sd-app-shell-sidebar-border-width) solid var(--sd-app-shell-sidebar-border);
  }

  /* Floating: the sidebar is the panel, the same paper and edge as the inset variant's, and the
     page stays on the canvas. */
  .sd-app-shell__sidebar[data-variant="floating"]:not([data-breakpoint="large"]) {
    margin: var(--sd-app-shell-panel-margin);
    background: var(--sd-app-shell-panel-background);
    border: var(--sd-app-shell-panel-border-width) solid var(--sd-app-shell-panel-border);
    border-radius: var(--sd-app-shell-panel-radius);
    corner-shape: superellipse(var(--sd-radius-curve));
  }

  /* Inset: the panel lifts off the canvas the sidebar stays on. Only beside a sidebar, which is the
     thing it separates from. It adds no padding of its own: the header and main keep theirs inside
     it, which is what keeps a card-in-a-frame from insetting the content twice. */
  .sd-app-shell__panel[data-variant="inset"][data-has-sidebar]:not([data-breakpoint="large"]) {
    margin: var(--sd-app-shell-panel-margin);
    background: var(--sd-app-shell-panel-background);
    border: var(--sd-app-shell-panel-border-width) solid var(--sd-app-shell-panel-border);
    border-radius: var(--sd-app-shell-panel-radius);
    corner-shape: superellipse(var(--sd-radius-curve));
  }

  /* Collapsed — the column narrows, the panel stays MOUNTED. Only the track changes, so the slot
     keeps its scroll position and focus; a consumer that dropped the slot instead would lose both.
     The width is ANIMATED, because the reflow is the feedback: an instant jump reads as a re-layout
     rather than as the panel the reader just folded. Motion is read directly under component-contract
     §6 carve-out 3, the global Sys constants. */
  .sd-app-shell[data-has-sidebar][data-sidebar-collapsed]:not([data-breakpoint="large"]) {
    /* `minmax(0, …)`, not the bare length: a grid track's automatic minimum is min-content, so
       `collapsedSidebarWidth="0"` floored at the width of whatever sat in the slot and the column
       never reached zero — measured on the story, ~20px of a placeholder still showing. Stating the
       minimum is what makes the documented zero case true. */
    grid-template-columns:
      minmax(0, var(--sd-app-shell-sidebar-collapsed-width, 5.5rem))
      minmax(0, 1fr);
  }
  /* Narrowed, the inset can be no wider than half the column, so `collapsedSidebarWidth="0"` leaves
     no transparent box over the page. The painted variants shrink their margin and edge the same
     way, or a zero-width column would still paint a rule or a panel's edge over the page.
     ponytail: each part is capped against the width on its own, so a collapsed width under about
     2rem can still overflow its track by a few px; a shared budget is the upgrade if anyone ships one. */
  .sd-app-shell__sidebar[data-collapsed][data-variant="floating"]:not([data-breakpoint="large"]) {
    margin: min(var(--sd-app-shell-panel-margin), calc(var(--sd-app-shell-sidebar-collapsed-width, 5.5rem) / 4));
    border-width: min(var(--sd-app-shell-panel-border-width), var(--sd-app-shell-sidebar-collapsed-width, 5.5rem));
  }
  .sd-app-shell__sidebar[data-collapsed][data-variant="divided"]:not([data-breakpoint="large"]) {
    border-inline-end-width: min(var(--sd-app-shell-sidebar-border-width), var(--sd-app-shell-sidebar-collapsed-width, 5.5rem));
  }
  .sd-app-shell__sidebar[data-collapsed]:not([data-breakpoint="large"]) {
    padding-inline: min(var(--sd-app-shell-sidebar-padding), calc(var(--sd-app-shell-sidebar-collapsed-width, 5.5rem) / 2));
  }

  .sd-app-shell[data-has-sidebar]:not([data-breakpoint="large"]) {
    transition: grid-template-columns var(--sd-duration-moderate) var(--sd-easing-standard);
  }

  /* With a rail: rail | sidebar | panel. The rail's track is `auto`, which interpolates into
     itself, so the sidebar's track still animates between its open width and zero. A rail is the
     trigger outside the sidebar's slot, so the tsx sets the collapsed width to zero, and every cap
     above takes the sidebar's padding, edge and margin to zero with it. */
  .sd-app-shell[data-has-rail]:not([data-breakpoint="large"]) {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .sd-app-shell[data-has-rail][data-has-sidebar]:not([data-breakpoint="large"]) {
    grid-template-columns: auto minmax(0, var(--sd-app-shell-sidebar-width, 16rem)) minmax(0, 1fr);
  }
  .sd-app-shell[data-has-rail][data-has-sidebar][data-sidebar-collapsed]:not([data-breakpoint="large"]) {
    grid-template-columns: auto minmax(0, var(--sd-app-shell-sidebar-collapsed-width)) minmax(0, 1fr);
  }
  /* A grid of one, so what the rail holds takes the track's whole height: a rail's footer pins to
     the window's foot only when the rail is as tall as the window. */
  .sd-app-shell__rail:not([data-breakpoint="large"]) {
    display: grid;
    transition: padding-inline-end var(--sd-duration-moderate) var(--sd-easing-standard);
  }
  /* An open sidebar's own leading inset is the one gap between the two columns, so the rail gives
     up its trailing one, and takes it back as the sidebar folds. A floating sidebar is its own
     paper, so the rail keeps its inset before it. Inset is the exception to taking it back: its
     panel stands off by its own margin whatever the sidebar does, so that margin is already the gap
     after a folded sidebar's zero-wide column, and the rail's trailing inset on top of it would
     count the gap twice, leaving the rail's items further from the panel than from the window.
     Plain and divided have no panel margin, and a folded floating sidebar's margin caps to zero,
     so their rail keeps its inset when the sidebar folds. */
  .sd-app-shell__rail[data-sidebar-open]:not([data-variant="floating"]):not([data-breakpoint="large"]),
  .sd-app-shell__rail[data-variant="inset"]:not([data-breakpoint="large"]) {
    padding-inline-end: 0;
  }

  /* Beside a rail the sidebar's content keeps the OPEN width whatever its column is, so folding
     slides it shut under the clip instead of reflowing it: a one-track grid at the open column less
     the sidebar's own inline inset, edge and margin. It clips open as well as folded, or the
     full-width content would paint over the page while the column grows back. Its inset, edge and
     margin travel with the column, so the content does not jump when a fold starts.
     Its one row is `minmax(0, 1fr)`, not the implicit `auto`: an auto row's minimum is its item's
     content, so a long list in the slot grew the row past the sidebar's own height and a ScrollArea
     inside never overflowed. Stating the minimum clamps the row to the sidebar, as the shell's own
     tracks are clamped above, and the slot's content scrolls inside it. */
  .sd-app-shell__sidebar[data-has-rail]:not([data-breakpoint="large"]) {
    display: grid;
    grid-template-columns: calc(
      var(--sd-app-shell-sidebar-width, 16rem) - var(--sd-app-shell-sidebar-padding) -
        var(--sd-app-shell-sidebar-gutter)
    );
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
    transition:
      padding-inline var(--sd-duration-moderate) var(--sd-easing-standard),
      margin var(--sd-duration-moderate) var(--sd-easing-standard),
      border-width var(--sd-duration-moderate) var(--sd-easing-standard);
  }
  .sd-app-shell__sidebar[data-has-rail][data-variant="divided"]:not([data-breakpoint="large"]) {
    grid-template-columns: calc(
      var(--sd-app-shell-sidebar-width, 16rem) - var(--sd-app-shell-sidebar-padding) -
        var(--sd-app-shell-sidebar-gutter) - var(--sd-app-shell-sidebar-border-width)
    );
  }
  .sd-app-shell__sidebar[data-has-rail][data-variant="floating"]:not([data-breakpoint="large"]) {
    grid-template-columns: calc(
      var(--sd-app-shell-sidebar-width, 16rem) -
        2 * (var(--sd-app-shell-panel-margin) + var(--sd-app-shell-panel-border-width)) - var(--sd-app-shell-sidebar-padding) -
        var(--sd-app-shell-sidebar-gutter)
    );
  }

  /* The variants with a rail. Divided: the rail and the sidebar are one section of the page, so
     the rail takes the same backdrop, and the rule stands at the region's end: on the sidebar while
     it is open (above), on the rail when the sidebar is folded or absent. Floating: the sidebar
     alone is the lifted panel and the rail stays on the canvas, so a folded sidebar leaves the
     navigation where it was. Inset: both stay on the canvas beside the panel, as a sidebar does. */
  .sd-app-shell__rail[data-variant="divided"]:not([data-breakpoint="large"]) {
    background: var(--sd-app-shell-sidebar-background);
  }
  .sd-app-shell__rail[data-variant="divided"]:not([data-sidebar-open]):not([data-breakpoint="large"]) {
    border-inline-end: var(--sd-app-shell-sidebar-border-width) solid var(--sd-app-shell-sidebar-border);
  }
}

/* The same wide layout from the large step instead, where a product switches there (`breakpoint="large"`).
   Generated as a copy of the block above with the opposite qualifier, so the two can never disagree. */
@media (min-width: 1024px) {
  /* BOTH tracks are `minmax(0, …)`, and the expanded one needs it for a reason that is not its own:
     a track only interpolates into a track of the SAME shape, so a bare length here against a
     `minmax()` when collapsed made the transition below inert — measured, the column jumped
     256 -> 56 in one frame with the transition property correctly applied. */
  .sd-app-shell[data-has-sidebar][data-breakpoint="large"] {
    grid-template-columns: minmax(0, var(--sd-app-shell-sidebar-width, 16rem)) minmax(0, 1fr);
  }
  /* the sidebar element only exists when a sidebar is provided (data-has-sidebar), so
     revealing it here needs no extra qualifier — no descendant combinator. */
  .sd-app-shell__sidebar[data-breakpoint="large"] {
    display: block;
  }
  /* Both routes to the navigation that only exist without the column. Hidden, not unmounted, so a
     stateful trigger survives the step, and a trigger-only bar leaves no empty band above the page. */
  .sd-app-shell__nav-trigger[data-breakpoint="large"],
  .sd-app-shell__nav-bar[data-breakpoint="large"],
  .sd-app-shell__bottom-nav[data-breakpoint="large"] {
    display: none;
  }
  .sd-app-shell__main[data-has-bottom-nav]:not([data-has-bottom-bar])[data-breakpoint="large"] {
    padding-block-end: var(--sd-app-shell-main-padding-block);
  }

  /* Divided: the sidebar is a section of the page plane, one backdrop step off it, behind a rule. */
  .sd-app-shell__sidebar[data-variant="divided"][data-breakpoint="large"] {
    background: var(--sd-app-shell-sidebar-background);
    border-inline-end: var(--sd-app-shell-sidebar-border-width) solid var(--sd-app-shell-sidebar-border);
  }

  /* Floating: the sidebar is the panel, the same paper and edge as the inset variant's, and the
     page stays on the canvas. */
  .sd-app-shell__sidebar[data-variant="floating"][data-breakpoint="large"] {
    margin: var(--sd-app-shell-panel-margin);
    background: var(--sd-app-shell-panel-background);
    border: var(--sd-app-shell-panel-border-width) solid var(--sd-app-shell-panel-border);
    border-radius: var(--sd-app-shell-panel-radius);
    corner-shape: superellipse(var(--sd-radius-curve));
  }

  /* Inset: the panel lifts off the canvas the sidebar stays on. Only beside a sidebar, which is the
     thing it separates from. It adds no padding of its own: the header and main keep theirs inside
     it, which is what keeps a card-in-a-frame from insetting the content twice. */
  .sd-app-shell__panel[data-variant="inset"][data-has-sidebar][data-breakpoint="large"] {
    margin: var(--sd-app-shell-panel-margin);
    background: var(--sd-app-shell-panel-background);
    border: var(--sd-app-shell-panel-border-width) solid var(--sd-app-shell-panel-border);
    border-radius: var(--sd-app-shell-panel-radius);
    corner-shape: superellipse(var(--sd-radius-curve));
  }

  /* Collapsed — the column narrows, the panel stays MOUNTED. Only the track changes, so the slot
     keeps its scroll position and focus; a consumer that dropped the slot instead would lose both.
     The width is ANIMATED, because the reflow is the feedback: an instant jump reads as a re-layout
     rather than as the panel the reader just folded. Motion is read directly under component-contract
     §6 carve-out 3, the global Sys constants. */
  .sd-app-shell[data-has-sidebar][data-sidebar-collapsed][data-breakpoint="large"] {
    /* `minmax(0, …)`, not the bare length: a grid track's automatic minimum is min-content, so
       `collapsedSidebarWidth="0"` floored at the width of whatever sat in the slot and the column
       never reached zero — measured on the story, ~20px of a placeholder still showing. Stating the
       minimum is what makes the documented zero case true. */
    grid-template-columns:
      minmax(0, var(--sd-app-shell-sidebar-collapsed-width, 5.5rem))
      minmax(0, 1fr);
  }
  /* Narrowed, the inset can be no wider than half the column, so `collapsedSidebarWidth="0"` leaves
     no transparent box over the page. The painted variants shrink their margin and edge the same
     way, or a zero-width column would still paint a rule or a panel's edge over the page.
     ponytail: each part is capped against the width on its own, so a collapsed width under about
     2rem can still overflow its track by a few px; a shared budget is the upgrade if anyone ships one. */
  .sd-app-shell__sidebar[data-collapsed][data-variant="floating"][data-breakpoint="large"] {
    margin: min(var(--sd-app-shell-panel-margin), calc(var(--sd-app-shell-sidebar-collapsed-width, 5.5rem) / 4));
    border-width: min(var(--sd-app-shell-panel-border-width), var(--sd-app-shell-sidebar-collapsed-width, 5.5rem));
  }
  .sd-app-shell__sidebar[data-collapsed][data-variant="divided"][data-breakpoint="large"] {
    border-inline-end-width: min(var(--sd-app-shell-sidebar-border-width), var(--sd-app-shell-sidebar-collapsed-width, 5.5rem));
  }
  .sd-app-shell__sidebar[data-collapsed][data-breakpoint="large"] {
    padding-inline: min(var(--sd-app-shell-sidebar-padding), calc(var(--sd-app-shell-sidebar-collapsed-width, 5.5rem) / 2));
  }

  .sd-app-shell[data-has-sidebar][data-breakpoint="large"] {
    transition: grid-template-columns var(--sd-duration-moderate) var(--sd-easing-standard);
  }

  /* With a rail: rail | sidebar | panel. The rail's track is `auto`, which interpolates into
     itself, so the sidebar's track still animates between its open width and zero. A rail is the
     trigger outside the sidebar's slot, so the tsx sets the collapsed width to zero, and every cap
     above takes the sidebar's padding, edge and margin to zero with it. */
  .sd-app-shell[data-has-rail][data-breakpoint="large"] {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .sd-app-shell[data-has-rail][data-has-sidebar][data-breakpoint="large"] {
    grid-template-columns: auto minmax(0, var(--sd-app-shell-sidebar-width, 16rem)) minmax(0, 1fr);
  }
  .sd-app-shell[data-has-rail][data-has-sidebar][data-sidebar-collapsed][data-breakpoint="large"] {
    grid-template-columns: auto minmax(0, var(--sd-app-shell-sidebar-collapsed-width)) minmax(0, 1fr);
  }
  /* A grid of one, so what the rail holds takes the track's whole height: a rail's footer pins to
     the window's foot only when the rail is as tall as the window. */
  .sd-app-shell__rail[data-breakpoint="large"] {
    display: grid;
    transition: padding-inline-end var(--sd-duration-moderate) var(--sd-easing-standard);
  }
  /* An open sidebar's own leading inset is the one gap between the two columns, so the rail gives
     up its trailing one, and takes it back as the sidebar folds. A floating sidebar is its own
     paper, so the rail keeps its inset before it. Inset is the exception to taking it back: its
     panel stands off by its own margin whatever the sidebar does, so that margin is already the gap
     after a folded sidebar's zero-wide column, and the rail's trailing inset on top of it would
     count the gap twice, leaving the rail's items further from the panel than from the window.
     Plain and divided have no panel margin, and a folded floating sidebar's margin caps to zero,
     so their rail keeps its inset when the sidebar folds. */
  .sd-app-shell__rail[data-sidebar-open]:not([data-variant="floating"])[data-breakpoint="large"],
  .sd-app-shell__rail[data-variant="inset"][data-breakpoint="large"] {
    padding-inline-end: 0;
  }

  /* Beside a rail the sidebar's content keeps the OPEN width whatever its column is, so folding
     slides it shut under the clip instead of reflowing it: a one-track grid at the open column less
     the sidebar's own inline inset, edge and margin. It clips open as well as folded, or the
     full-width content would paint over the page while the column grows back. Its inset, edge and
     margin travel with the column, so the content does not jump when a fold starts.
     Its one row is `minmax(0, 1fr)`, not the implicit `auto`: an auto row's minimum is its item's
     content, so a long list in the slot grew the row past the sidebar's own height and a ScrollArea
     inside never overflowed. Stating the minimum clamps the row to the sidebar, as the shell's own
     tracks are clamped above, and the slot's content scrolls inside it. */
  .sd-app-shell__sidebar[data-has-rail][data-breakpoint="large"] {
    display: grid;
    grid-template-columns: calc(
      var(--sd-app-shell-sidebar-width, 16rem) - var(--sd-app-shell-sidebar-padding) -
        var(--sd-app-shell-sidebar-gutter)
    );
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
    transition:
      padding-inline var(--sd-duration-moderate) var(--sd-easing-standard),
      margin var(--sd-duration-moderate) var(--sd-easing-standard),
      border-width var(--sd-duration-moderate) var(--sd-easing-standard);
  }
  .sd-app-shell__sidebar[data-has-rail][data-variant="divided"][data-breakpoint="large"] {
    grid-template-columns: calc(
      var(--sd-app-shell-sidebar-width, 16rem) - var(--sd-app-shell-sidebar-padding) -
        var(--sd-app-shell-sidebar-gutter) - var(--sd-app-shell-sidebar-border-width)
    );
  }
  .sd-app-shell__sidebar[data-has-rail][data-variant="floating"][data-breakpoint="large"] {
    grid-template-columns: calc(
      var(--sd-app-shell-sidebar-width, 16rem) -
        2 * (var(--sd-app-shell-panel-margin) + var(--sd-app-shell-panel-border-width)) - var(--sd-app-shell-sidebar-padding) -
        var(--sd-app-shell-sidebar-gutter)
    );
  }

  /* The variants with a rail. Divided: the rail and the sidebar are one section of the page, so
     the rail takes the same backdrop, and the rule stands at the region's end: on the sidebar while
     it is open (above), on the rail when the sidebar is folded or absent. Floating: the sidebar
     alone is the lifted panel and the rail stays on the canvas, so a folded sidebar leaves the
     navigation where it was. Inset: both stay on the canvas beside the panel, as a sidebar does. */
  .sd-app-shell__rail[data-variant="divided"][data-breakpoint="large"] {
    background: var(--sd-app-shell-sidebar-background);
  }
  .sd-app-shell__rail[data-variant="divided"]:not([data-sidebar-open])[data-breakpoint="large"] {
    border-inline-end: var(--sd-app-shell-sidebar-border-width) solid var(--sd-app-shell-sidebar-border);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-app-shell[data-has-sidebar],
  .sd-app-shell__rail,
  .sd-app-shell__sidebar[data-has-rail] {
    transition: none;
  }
}
